/// Deterministic, synthetic sample data bundled with the app.
///
/// This is clearly-labelled synthetic data generated by a seeded geometric
/// Brownian motion — it is NOT real market data. It exists so the app is usable
/// and demonstrable offline, out of the box, without any network or API key.
library;

import 'dart:math' as math;

import '../models/candle.dart';
import '../models/dataset.dart';

class SampleSeries {
  final String symbol;
  final BarInterval interval;
  final List<Candle> candles;
  const SampleSeries({required this.symbol, required this.interval, required this.candles});
}

class SampleData {
  const SampleData._();

  /// Generates [bars] synthetic candles via a seeded GBM with realistic
  /// intra-bar high/low structure.
  static List<Candle> generate({
    required String symbol,
    required int bars,
    required BarInterval interval,
    double startPrice = 100,
    double annualDrift = 0.08,
    double annualVol = 0.25,
    int seed = 42,
  }) {
    final rnd = math.Random(seed);
    final stepYears = interval.duration.inSeconds / (365.25 * 24 * 3600);
    final mu = annualDrift * stepYears;
    final sigma = annualVol * math.sqrt(stepYears);

    // End the series at "now" aligned to the interval.
    final now = DateTime.utc(2026, 10, 15);
    final startTime = now.subtract(interval.duration * bars);

    var price = startPrice;
    final candles = <Candle>[];
    for (var i = 0; i < bars; i++) {
      final open = price;
      final shock = _gauss(rnd) * sigma + mu;
      final close = open * math.exp(shock);
      final wick = open * sigma * 0.9 * (0.3 + rnd.nextDouble());
      final high = math.max(open, close) + wick * rnd.nextDouble();
      final low = math.min(open, close) - wick * rnd.nextDouble();
      final volume = (500000 + rnd.nextDouble() * 1500000) * (1 + (shock.abs() * 10));
      candles.add(Candle(
        time: startTime.add(interval.duration * i).toUtc(),
        open: _round(open),
        high: _round(math.max(high, math.max(open, close))),
        low: _round(math.max(0.01, math.min(low, math.min(open, close)))),
        close: _round(close),
        volume: volume.roundToDouble(),
      ));
      price = close;
    }
    return candles;
  }

  static double _gauss(math.Random r) {
    // Box–Muller transform.
    final u1 = r.nextDouble().clamp(1e-9, 1.0);
    final u2 = r.nextDouble();
    return math.sqrt(-2 * math.log(u1)) * math.cos(2 * math.pi * u2);
  }

  static double _round(double v) => (v * 100).roundToDouble() / 100;

  /// The set of sample series offered in the Data screen.
  static List<SampleSeries> bundled() => [
        SampleSeries(
          symbol: 'NIFTY 50 (sample)',
          interval: BarInterval.d1,
          candles: generate(symbol: 'NIFTY50', bars: 1500, interval: BarInterval.d1, startPrice: 22000, annualDrift: 0.11, annualVol: 0.18, seed: 7),
        ),
        SampleSeries(
          symbol: 'RELIANCE (sample)',
          interval: BarInterval.d1,
          candles: generate(symbol: 'RELIANCE', bars: 1200, interval: BarInterval.d1, startPrice: 2400, annualDrift: 0.10, annualVol: 0.26, seed: 11),
        ),
        SampleSeries(
          symbol: 'BTC-USD (sample)',
          interval: BarInterval.d1,
          candles: generate(symbol: 'BTCUSD', bars: 1000, interval: BarInterval.d1, startPrice: 42000, annualDrift: 0.35, annualVol: 0.65, seed: 23),
        ),
      ];
}
